# Generated by manage.py generate_test_cases.
"""Verify authenticated original-byte downloads and revocable reference access."""

from uuid import uuid4

from django.core.files.uploadedfile import SimpleUploadedFile
from django.http import HttpResponse
from django.test import override_settings
from django.urls import reverse

from bloomerp.config.definition import (
    ApiKeyAuthSettings,
    BloomerpAuthSettings,
    BloomerpConfig,
)
from bloomerp.models import FileNode
from bloomerp.models.api.api_key import ApiKey
from bloomerp.permissions.definition import BloomerpPermission, RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.tests.base import BloomerpAPIViewTestCase, ExpectedResult, RequestScenario


class TestFileDownloadView(BloomerpAPIViewTestCase):
    """Exercise actual routing and credential authentication without browser cookies."""

    view_name = "api_file_download"
    auto_create_customers = False

    def extendedSetup(self) -> None:
        """Create a private binary file in test media storage."""
        self.original = b"\x00\xff\x80binary\r\n"
        self.file = FileNode.objects.create(
            content=SimpleUploadedFile("Résumé spaced.pdf", self.original),
            kind="FILE",
            created_by=self.admin_user,
            updated_by=self.admin_user,
        )

    def original_download(self, response: HttpResponse) -> bool:
        """Verify exact binary bytes and safe private attachment headers."""
        self.assertEqual(b"".join(response.streaming_content), self.original)
        self.assertEqual(response["Content-Type"], "application/pdf")
        self.assertEqual(response["Cache-Control"], "private, no-store")
        self.assertEqual(response["X-Content-Type-Options"], "nosniff")
        self.assertTrue(response["Content-Disposition"].startswith("attachment;"))
        return True

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover permitted, denied, missing, invalid and anonymous file requests."""
        return [
            RequestScenario(
                name="Download binary original",
                user=self.admin_user,
                query_params={"file_id": str(self.file.pk)},
                expected=ExpectedResult(response_validators=self.original_download),
            ),
            RequestScenario(
                name="Other user cannot retrieve upload",
                user=self.normal_user,
                query_params={"file_id": str(self.file.pk)},
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Anonymous request requires authentication",
                query_params={"file_id": str(self.file.pk)},
                expected=ExpectedResult(status_code=401),
            ),
            RequestScenario(
                name="Missing ID remains unavailable",
                user=self.admin_user,
                query_params={"file_id": str(uuid4())},
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Invalid ID is rejected",
                user=self.admin_user,
                query_params={"file_id": "invalid"},
                expected=ExpectedResult(status_code=400),
            ),
        ]

    @override_settings(
        BLOOMERP_CONFIG=BloomerpConfig(
            auto_generate_api_endpoints=True,
            auth=BloomerpAuthSettings(api_key=ApiKeyAuthSettings(enabled=True)),
        )
    )
    def test_api_key_upload_read_download_round_trip(self) -> None:
        """Round-trip text and binary bytes using only real API-key Bearer headers."""
        import base64

        api_key = ApiKey(account=self.admin_user, name="Synthetic file test")
        token = api_key.set_token()
        api_key.save()
        headers = {"HTTP_AUTHORIZATION": f"Bearer {token}"}
        for name, original in [
            ("hello.txt", "Hello résumé".encode()),
            ("binary.pdf", self.original),
        ]:
            with self.subTest(name=name):
                uploaded = self.client.post(
                    reverse("api_assistant_file_upload"),
                    {"file": SimpleUploadedFile(name, original)},
                    **headers,
                )
                self.assertEqual(uploaded.status_code, 201, uploaded.content)
                file_id = uploaded.json()["file_id"]
                read = self.client.post(
                    reverse("api_file_read"),
                    {"file_id": file_id},
                    content_type="application/json",
                    **headers,
                )
                self.assertEqual(read.status_code, 200, read.content)
                self.assertEqual(
                    base64.b64decode(read.json()["content_base64"]), original
                )
                downloaded = self.client.get(read.json()["download_path"], **headers)
                self.assertEqual(downloaded.status_code, 200)
                self.assertEqual(b"".join(downloaded.streaming_content), original)
        api_key.delete()
        denied = self.client.get(
            reverse("api_file_download"), {"file_id": str(self.file.pk)}, **headers
        )
        self.assertEqual(denied.status_code, 401)

    def test_field_read_permission_is_rechecked_after_revocation(self) -> None:
        """A successful metadata lookup never grants a later download permission."""
        customer = self.create_customer("Private", "Resume", 30)
        field = self.CustomerModel._meta.get_field("picture")
        field.on_save(
            customer,
            [],
            [SimpleUploadedFile("resume.pdf", b"private resume")],
            user=self.admin_user,
        )
        file_id = str(customer.picture[0].pk)
        policy = PolicyManager.create_policy(
            model_or_content_type=self.CustomerModel,
            field_permissions={"picture": [BloomerpPermission.VIEW]},
            row_permissions=[
                RowPolicyRuleContent(
                    permissions=[BloomerpPermission.VIEW], conditions=[]
                )
            ],
        )
        policy.users.add(self.normal_user)
        self.client.force_login(self.normal_user)
        read = self.client.post(
            reverse("api_file_read"),
            {"file_id": file_id},
            content_type="application/json",
        )
        self.assertEqual(read.status_code, 200, read.content)
        policy.users.remove(self.normal_user)
        response = self.client.get(read.json()["download_path"])
        self.assertEqual(response.status_code, 404)
        self.assertNotIn(b"resume", response.content)
        self.assertNotIn(b"bloomerp/files", response.content)
